import type { ProviderCapabilities } from '../../core/capabilities.js';
import { lines, oneLine, SDK_PACKAGE, type GeneratedFile } from './shared.js';

/**
 * Infinity publishes no API, so like Skydo its integration is an invoice (Zoho Books bridge) or
 * bank-transfer instructions and/or a QuickLink (ledger) instead of a checkout, and status polling
 * (Zoho) or an admin "money arrived" action (ledger) instead of webhooks.
 */

const SERVICE = `/**
 * Infinity payments (generated by ${SDK_PACKAGE}).
 *
 * Infinity (infinityapp.in) publishes no developer API or webhooks. The SDK automates what Infinity offers:
 *  - Zoho Books bridge (INFINITY_ZOHO_* set): we create a Zoho invoice for Infinity's Zoho integration
 *    (Infinity dashboard > Connect > Zoho Books) and poll Zoho; paid = Zoho payments cover the total.
 *  - Ledger mode: we hand the client your Infinity account details (with the order reference) and/or a
 *    QuickLink you created in the dashboard; an admin records the receipt once the dashboard shows it.
 */
import { createPaymentsClient, PaymentError, toMajorString, type PaymentStatus } from '${SDK_PACKAGE}';

export const payments = createPaymentsClient({ actor: 'app:infinity' });

export interface ExportInvoice {
  /** 3-40 chars, letters/digits/_/-. Used as the bank transfer reference: put it in the Infinity invoice number too. */
  orderRef: string;
  /** Minor units of the client's currency: USD 1,250.00 = 125000. */
  amount: number;
  currency: string;
  customer: { name?: string; email: string };
  description: string;
  status: PaymentStatus;
  fulfilled: boolean;
  /** Zoho invoice id (Zoho bridge) or infinity:<orderRef> (ledger). Lets a refresh cost one Zoho call. */
  providerOrderId?: string;
}

// TODO: replace with your database (an invoices / orders table).
const invoices = new Map<string, ExportInvoice>();

export async function loadInvoice(orderRef: string): Promise<ExportInvoice | undefined> {
  return invoices.get(orderRef);
}

async function saveInvoice(inv: ExportInvoice): Promise<void> {
  invoices.set(inv.orderRef, inv);
}

/** Called once per invoice. MUST be idempotent: polling and admin actions can both reach it. */
async function onPaid(inv: ExportInvoice): Promise<void> {
  // TODO: mark the order paid, release deliverables, email the client a receipt.
  console.log(\`Infinity payment received for \${inv.orderRef}: \${inv.currency} \${toMajorString(inv.amount, inv.currency)}\`);
}

/**
 * Payment instructions for an order YOU priced. quickLinkUrl is optional: create the QuickLink in the
 * Infinity dashboard for the same amount and currency, then pass the copied link.
 */
export async function requestPayment(inv: Omit<ExportInvoice, 'status' | 'fulfilled' | 'providerOrderId'>, quickLinkUrl?: string) {
  const existing = await loadInvoice(inv.orderRef);
  const created = await payments.createPayment('infinity', {
    orderRef: inv.orderRef,
    amount: inv.amount,
    currency: inv.currency,
    customer: inv.customer,
    description: inv.description,
    ...(quickLinkUrl ? { providerOptions: { quickLinkUrl } } : {}),
  });
  // Asking again (e.g. to resend the instructions) must never reset an order that was already fulfilled.
  await saveInvoice({ ...inv, status: existing?.status ?? created.status, fulfilled: existing?.fulfilled ?? false, providerOrderId: created.providerOrderId });
  // checkout.type is always "manual" for Infinity: instructions for your client (+ the QuickLink or Zoho invoice link).
  if (created.checkout.type !== 'manual') throw new Error('unexpected checkout type');
  return { orderRef: inv.orderRef, instructions: created.checkout.instructions, paymentUrl: created.checkout.url };
}

/** Read the authoritative status (Zoho invoice or ledger) and fulfil exactly once. */
export async function refreshStatus(orderRef: string): Promise<PaymentStatus> {
  const inv = await loadInvoice(orderRef);
  if (!inv) throw new PaymentError('NOT_FOUND', \`Unknown invoice \${orderRef}\`);
  const v = await payments.verifyPayment('infinity', { orderRef, expectedAmount: inv.amount, providerOrderId: inv.providerOrderId, payload: {} });
  inv.status = v.status;
  if (v.paid && !inv.fulfilled) {
    inv.fulfilled = true;
    await saveInvoice(inv);
    await onPaid(inv);
  } else {
    await saveInvoice(inv);
  }
  return inv.status;
}

/**
 * Zoho bridge: Infinity has no webhooks, so poll unpaid invoices: one Zoho API call per open invoice.
 * Zoho Books allows 100 calls/minute and 1,000 (Free) to 10,000 (Premium+) calls/day per organisation.
 * At the default 15-minute interval each open invoice costs 96 calls/day.
 */
export async function pollUnpaid(): Promise<void> {
  for (const inv of invoices.values()) {
    if (inv.fulfilled || inv.status === 'cancelled') continue;
    try {
      await refreshStatus(inv.orderRef);
    } catch (err) {
      payments.logger.warn('infinity.poll_failed', { orderRef: inv.orderRef, err: String(err) });
    }
  }
}

/**
 * Ledger mode: an admin confirms money the Infinity dashboard shows as received. Check it there first: a link
 * being opened, or a client saying they paid, is not a payment.
 * receiptId = the Infinity transaction reference: recording it twice is a no-op.
 */
export async function recordReceipt(input: { orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string }) {
  await payments.infinityRecordPayment(input);
  return refreshStatus(input.orderRef);
}

/** Cheap status for customers/front-ends: our own record only, never a Zoho call (protects your Zoho API quota). */
export async function storedStatus(orderRef: string): Promise<PaymentStatus | undefined> {
  return (await loadInvoice(orderRef))?.status;
}

/** Ledger mode: what clients still owe you, oldest first. */
export async function outstanding() {
  return payments.infinityOutstanding();
}
`;

const ADMIN_CHECK = `import { timingSafeEqual } from 'node:crypto';

/** Replace with your real admin auth. Recording a receipt marks an order paid. */
export function assertAdmin(authorization: string | undefined): void {
  const token = process.env.ADMIN_API_TOKEN ?? '';
  const got = Buffer.from((authorization ?? '').replace(/^Bearer\\s+/i, ''));
  const want = Buffer.from(token);
  if (!token || got.length !== want.length || !timingSafeEqual(got, want)) {
    throw Object.assign(new Error('Forbidden'), { status: 403 });
  }
}
`;

const EXAMPLE_ORDER = `const order = { amount: 125000, currency: 'USD', customer: { name: 'Globex Corp', email: 'ap@globex.example' }, description: 'Design retainer, March' };`;

const RECEIPT_BODY = 'orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string';

function expressRoutes(): string {
  return `import express, { type NextFunction, type Request, type Response } from 'express';
import { PaymentError } from '${SDK_PACKAGE}';
import { assertAdmin } from './admin.js';
import { outstanding, pollUnpaid, recordReceipt, refreshStatus, requestPayment, storedStatus } from './infinity.js';

export const infinityRouter = express.Router();
infinityRouter.use(express.json());

const wrap = (fn: (req: Request, res: Response) => Promise<unknown>) => (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);

// Admin: create the payment instructions. Price it on the SERVER, never from the request body.
// The QuickLink (optional) is one you created in the Infinity dashboard for this order.
infinityRouter.post('/api/infinity/invoices', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  const { orderId, quickLinkUrl } = req.body as { orderId?: string; quickLinkUrl?: string };
  if (!orderId) return void res.status(400).json({ error: 'orderId required' });
  // TODO: load the order from your database. Example values:
  ${EXAMPLE_ORDER}
  res.status(201).json(await requestPayment({ orderRef: orderId, ...order }, quickLinkUrl));
}));

// Public: answers from your own records.
infinityRouter.get('/api/infinity/invoices/:orderRef', wrap(async (req, res) => {
  const status = await storedStatus(String(req.params.orderRef));
  if (!status) return void res.status(404).json({ error: 'NOT_FOUND' });
  res.json({ orderRef: req.params.orderRef, status });
}));

// Admin: re-read the authoritative status now (Zoho invoice or ledger).
infinityRouter.post('/api/infinity/invoices/:orderRef/refresh', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  res.json({ orderRef: req.params.orderRef, status: await refreshStatus(String(req.params.orderRef)) });
}));

// Ledger mode only: an admin records money the Infinity dashboard shows as received.
infinityRouter.post('/api/infinity/receipts', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  const { orderRef, receiptId, amountReceived, firaNumber, note } = req.body as { ${RECEIPT_BODY} };
  res.json({ orderRef, status: await recordReceipt({ orderRef, receiptId, amountReceived, firaNumber, note }) });
}));

infinityRouter.get('/api/infinity/outstanding', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  res.json(await outstanding());
}));

infinityRouter.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
  if (err instanceof PaymentError) return void res.status(err.code === 'NOT_FOUND' ? 404 : 400).json(err.toJSON());
  const status = (err as { status?: number }).status ?? 500;
  res.status(status).json({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' });
});

/** Zoho bridge: start polling. Ledger mode needs no polling (an admin records receipts). */
export function startInfinityPolling(intervalMs = 15 * 60_000) {
  return setInterval(() => void pollUnpaid(), intervalMs);
}
`;
}

function expressServer(): string {
  return `import express from 'express';
import { infinityRouter, startInfinityPolling } from './payments/infinity-routes.js';

const app = express();
app.use(infinityRouter);
const port = Number(process.env.PORT ?? 3000);
app.listen(port, () => console.log(\`Infinity payments on http://localhost:\${port}\`));
if (process.env.INFINITY_ZOHO_REFRESH_TOKEN) startInfinityPolling();
`;
}

function nextRoutes(): GeneratedFile[] {
  const imp = `import { NextResponse } from 'next/server';
import { PaymentError } from '${SDK_PACKAGE}';`;
  const errors = `function fail(err: unknown) {
  if (err instanceof PaymentError) return NextResponse.json(err.toJSON(), { status: err.code === 'NOT_FOUND' ? 404 : 400 });
  const status = (err as { status?: number }).status ?? 500;
  return NextResponse.json({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' }, { status });
}`;
  return [
    {
      path: 'app/api/infinity/invoices/route.ts',
      language: 'typescript',
      contents: `${imp}
import { assertAdmin } from '@/lib/payments/admin';
import { requestPayment } from '@/lib/payments/infinity';

export const runtime = 'nodejs';

${errors}

/** Admin: create payment instructions (+ optional QuickLink from the Infinity dashboard). */
export async function POST(req: Request) {
  try {
    assertAdmin(req.headers.get('authorization') ?? undefined);
    const { orderId, quickLinkUrl } = (await req.json()) as { orderId?: string; quickLinkUrl?: string };
    if (!orderId) return NextResponse.json({ error: 'orderId required' }, { status: 400 });
    // TODO: load the order from your database. Never trust an amount from the browser.
    ${EXAMPLE_ORDER}
    return NextResponse.json(await requestPayment({ orderRef: orderId, ...order }, quickLinkUrl), { status: 201 });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/infinity/invoices/[orderRef]/route.ts',
      language: 'typescript',
      contents: `${imp}
import { storedStatus } from '@/lib/payments/infinity';

export const runtime = 'nodejs';

${errors}

/** Public: answers from your own records. */
export async function GET(_req: Request, { params }: { params: Promise<{ orderRef: string }> }) {
  try {
    const { orderRef } = await params;
    const status = await storedStatus(orderRef);
    if (!status) return NextResponse.json({ error: 'NOT_FOUND' }, { status: 404 });
    return NextResponse.json({ orderRef, status });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/infinity/receipts/route.ts',
      language: 'typescript',
      contents: `${imp}
import { assertAdmin } from '@/lib/payments/admin';
import { recordReceipt } from '@/lib/payments/infinity';

export const runtime = 'nodejs';

${errors}

/** Ledger mode only: an admin records money the Infinity dashboard shows as received. */
export async function POST(req: Request) {
  try {
    assertAdmin(req.headers.get('authorization') ?? undefined);
    const body = (await req.json()) as { ${RECEIPT_BODY} };
    return NextResponse.json({ orderRef: body.orderRef, status: await recordReceipt(body) });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/infinity/poll/route.ts',
      language: 'typescript',
      contents: `${imp}
import { assertAdmin } from '@/lib/payments/admin';
import { pollUnpaid } from '@/lib/payments/infinity';

export const runtime = 'nodejs';

${errors}

/** Zoho bridge: call from a cron (e.g. Vercel Cron every 15 min). Infinity has no webhooks. */
export async function POST(req: Request) {
  try {
    assertAdmin(req.headers.get('authorization') ?? undefined);
    await pollUnpaid();
    return NextResponse.json({ ok: true });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
  ];
}

function fastifyPlugin(): string {
  return `import type { FastifyInstance } from 'fastify';
import { PaymentError } from '${SDK_PACKAGE}';
import { assertAdmin } from './admin.js';
import { outstanding, pollUnpaid, recordReceipt, refreshStatus, requestPayment, storedStatus } from './infinity.js';

/** Zoho bridge: call once at startup, e.g. \`if (process.env.INFINITY_ZOHO_REFRESH_TOKEN) startInfinityPolling()\`. */
export function startInfinityPolling(intervalMs = 15 * 60_000) {
  return setInterval(() => void pollUnpaid(), intervalMs);
}

export async function infinityRoutes(app: FastifyInstance) {
  app.setErrorHandler((err, _req, reply) => {
    if (err instanceof PaymentError) return reply.code(err.code === 'NOT_FOUND' ? 404 : 400).send(err.toJSON());
    const status = (err as { status?: number }).status ?? 500;
    return reply.code(status).send({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' });
  });

  app.post<{ Body: { orderId?: string; quickLinkUrl?: string } }>('/api/infinity/invoices', async (req, reply) => {
    assertAdmin(req.headers.authorization);
    if (!req.body?.orderId) return reply.code(400).send({ error: 'orderId required' });
    // TODO: load the order from your database. Never trust an amount from the browser.
    ${EXAMPLE_ORDER}
    return reply.code(201).send(await requestPayment({ orderRef: req.body.orderId, ...order }, req.body.quickLinkUrl));
  });

  app.get<{ Params: { orderRef: string } }>('/api/infinity/invoices/:orderRef', async (req, reply) => {
    const status = await storedStatus(req.params.orderRef);
    if (!status) return reply.code(404).send({ error: 'NOT_FOUND' });
    return { orderRef: req.params.orderRef, status };
  });

  app.post<{ Params: { orderRef: string } }>('/api/infinity/invoices/:orderRef/refresh', async (req) => {
    assertAdmin(req.headers.authorization);
    return { orderRef: req.params.orderRef, status: await refreshStatus(req.params.orderRef) };
  });

  app.post<{ Body: { ${RECEIPT_BODY} } }>('/api/infinity/receipts', async (req) => {
    assertAdmin(req.headers.authorization);
    return { orderRef: req.body.orderRef, status: await recordReceipt(req.body) };
  });

  app.get('/api/infinity/outstanding', async (req) => {
    assertAdmin(req.headers.authorization);
    return outstanding();
  });
}
`;
}

export function infinityGuide(cap: ProviderCapabilities): string {
  return lines(
    `# Collecting international payments with Infinity`,
    ``,
    `Infinity (infinityapp.in) publishes **no developer API docs, SDK or webhooks** (checked ${cap.lastVerified}).`,
    `Its Terms forbid reverse engineering and incorporating the Services into other systems without consent, so the generated`,
    `code never calls Infinity. It does what Infinity supports by hand, through the \`${SDK_PACKAGE}\` SDK.`,
    ``,
    `## Option A: Zoho Books bridge (if you use Zoho Books)`,
    ``,
    `1. In the Infinity dashboard: **Connect** tab > **Zoho Books**, and connect your Zoho organisation.`,
    `2. In Zoho Books: create a service item (its \`item_id\` is \`INFINITY_ZOHO_ITEM_ID\`) and each client once as a customer in their`,
    `   billing currency (GST treatment "Overseas" for Indian organisations). Turn off Zoho online payment gateways for these invoices.`,
    `3. Zoho API Console > **Self Client** > Generate Code with scope \`ZohoBooks.invoices.ALL,ZohoBooks.contacts.READ\`, exchange it`,
    `   for a refresh token at your region's accounts host (accounts.zoho.in for India) and set the \`INFINITY_ZOHO_*\` variables.`,
    `4. \`requestPayment()\` creates the Zoho invoice (reference = your order id) and marks it sent; \`pollUnpaid()\` (every 15 min)`,
    `   fulfils it once Zoho shows payments covering the total. Infinity does not publicly document what its Zoho integration`,
    `   syncs, so **during setup pay one small real invoice and confirm Infinity marks it paid in Zoho**. If it does not, use Option B.`,
    `5. Do not connect Skydo and Infinity to the same Zoho organisation.`,
    ``,
    `## Option B: receiving accounts and/or QuickLinks + ledger`,
    ``,
    `1. Copy your receiving account details from the Infinity dashboard into \`INFINITY_RECEIVING_ACCOUNTS\`:`,
    ``,
    '   ```json',
    `   [{"currency":"USD","label":"US account (ACH)","details":{"Account holder":"...","Account number":"...","ACH routing":"..."}},`,
    `    {"currency":"*","label":"SWIFT","details":{"SWIFT/BIC":"...","Account number":"..."}}]`,
    '   ```',
    ``,
    `   Or set \`INFINITY_QUICKLINK_ONLY=true\` to send QuickLinks only.`,
    `2. Optional QuickLink: in Infinity, Create invoice (invoice number = your order id, same amount and currency) >`,
    `   Payment details > Credit card > Review invoice, then copy the link and pass it as \`quickLinkUrl\`.`,
    `   Only https links on \`INFINITY_QUICKLINK_HOSTS\` (default *.infinityapp.in) are accepted. Check your first real link's host.`,
    `3. \`requestPayment()\` returns instructions with your order id as the payment reference (and the link). Send them to the client.`,
    `   The expected payment is tracked in \`INFINITY_LEDGER_FILE\`.`,
    `4. When the Infinity dashboard shows the payment received (or the QuickLink completed), call \`POST /api/infinity/receipts\``,
    `   (admin) with \`receiptId\` (the Infinity transaction reference) and the amount received in cents. Recording the same`,
    `   receiptId twice is a no-op; a short amount keeps the order pending. Do not record on a client's word or a forwarded email.`,
    ``,
    `## Things Infinity does not offer through code (so neither does this)`,
    ``,
    `- Checkout on your website, INR, UPI, refunds, webhooks; automatic status only through Zoho (Option A).`,
    `- Recurring charges: Infinity's recurring invoices are separate from payment links; raise one per billing period.`,
    ``,
    `## Constraints`,
    ``,
    ...cap.constraints.map((c) => `- ${oneLine(c)}`),
    ``,
  );
}

export function infinityFiles(framework: string): GeneratedFile[] {
  const files: GeneratedFile[] = [];
  if (framework === 'nextjs') {
    files.push({ path: 'lib/payments/infinity.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'lib/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push(...nextRoutes());
  } else if (framework === 'fastify') {
    files.push({ path: 'src/payments/infinity.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'src/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push({ path: 'src/payments/infinity-routes.ts', language: 'typescript', contents: fastifyPlugin() });
  } else {
    // express, react, html, mobile, other: an Express backend holds the ledger.
    files.push({ path: 'src/payments/infinity.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'src/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push({ path: 'src/payments/infinity-routes.ts', language: 'typescript', contents: expressRoutes() });
    files.push({ path: 'src/server.ts', language: 'typescript', contents: expressServer() });
  }
  return files;
}
